#include <hip/hip_runtime.h>
#include "fi_lite_hip.h"
constexpr unsigned EV_GEMM = 10;

extern "C" __global__ void gemm_one_element(
    float* c, const float* a, const float* b, int m, int n, int k) {
  FI_OPEN(0);
  const int row = blockIdx.x * blockDim.x + threadIdx.x;
  const int col = blockIdx.y * blockDim.y + threadIdx.y;
  if (row < m && col < n) {
    const unsigned aux = static_cast<unsigned>(row * n + col);
    FI_B(EV_GEMM, aux);
    float acc = 0.0f;
    for (int inner = 0; inner < k; ++inner) {
      acc = fmaf(a[row * k + inner], b[inner * n + col], acc);
    }
    FI_E(EV_GEMM, aux);
    c[row * n + col] = acc;
  }
  FI_CLOSE();
}

#include <hip/hip_runtime.h>
#include "fi_lite_hip.h"
constexpr unsigned EV_ATTENTION = 11;

extern "C" __global__ void attention_row(
    float* out, const float* q, const float* k, const float* v,
    int keys, int dim) {
  const unsigned linear = threadIdx.x + blockDim.x * (threadIdx.y + blockDim.y * threadIdx.z);
  if (linear != 0u) return;
  FI_OPEN(0);
  const int row = blockIdx.x;
  const float scale = rsqrtf(static_cast<float>(dim));
  FI_B(EV_ATTENTION, static_cast<unsigned>(row));
  float norm = 0.0f;
  for (int key = 0; key < keys; ++key) {
    float score = 0.0f;
    for (int d = 0; d < dim; ++d) score = fmaf(q[row * dim + d], k[key * dim + d], score);
    norm += expf(score * scale);
  }
  for (int d = 0; d < dim; ++d) {
    float acc = 0.0f;
    for (int key = 0; key < keys; ++key) {
      float score = 0.0f;
      for (int e = 0; e < dim; ++e) score = fmaf(q[row * dim + e], k[key * dim + e], score);
      acc = fmaf(expf(score * scale) / norm, v[key * dim + d], acc);
    }
    out[row * dim + d] = acc;
  }
  FI_E(EV_ATTENTION, static_cast<unsigned>(row));
  FI_CLOSE();
}

#include <hip/hip_runtime.h>
#include "fi_lite_hip.h"
constexpr unsigned EV_SOFTMAX = 16;

extern "C" __global__ void softmax_row(float* out, const float* src, int width) {
  const unsigned linear = threadIdx.x + blockDim.x * (threadIdx.y + blockDim.y * threadIdx.z);
  if (linear != 0u) return;
  FI_OPEN(0);
  const int row = blockIdx.x;
  FI_B(EV_SOFTMAX, static_cast<unsigned>(row));
  float row_max = -INFINITY;
  for (int col = 0; col < width; ++col) row_max = fmaxf(row_max, src[row * width + col]);
  float denominator = 0.0f;
  for (int col = 0; col < width; ++col) denominator += expf(src[row * width + col] - row_max);
  for (int col = 0; col < width; ++col) out[row * width + col] = expf(src[row * width + col] - row_max) / denominator;
  FI_E(EV_SOFTMAX, static_cast<unsigned>(row));
  FI_CLOSE();
}

#include <hip/hip_runtime.h>
#include "fi_lite_hip.h"
constexpr unsigned EV_REDUCTION = 12;

extern "C" __global__ void wave_sum(const float* src, float* dst) {
  FI_OPEN(0);
  const unsigned linear = threadIdx.x + blockDim.x * (threadIdx.y + blockDim.y * threadIdx.z);
  const unsigned lane = linear & 63u;
  const unsigned wave = linear >> 6;
  const unsigned cta_waves = blockDim.x * blockDim.y * blockDim.z / 64u;
  const unsigned track = blockIdx.x * cta_waves + wave;
  float value = src[blockIdx.x * blockDim.x + linear];
  if (lane == 0u) FI_B(EV_REDUCTION, track);
  __syncthreads();
  for (int delta = 32; delta > 0; delta >>= 1) value += __shfl_down(value, delta, 64);
  __syncthreads();
  if (lane == 0u) {
    dst[track] = value;
    FI_E(EV_REDUCTION, track);
  }
  FI_CLOSE();
}

#include <hip/hip_runtime.h>
#include "fi_lite_hip.h"
constexpr unsigned EV_MOE = 13;

__device__ float expert_dot(const float* x, const float* w, int width) {
  float acc = 0.0f;
  for (int i = 0; i < width; ++i) acc = fmaf(x[i], w[i], acc);
  return acc;
}

extern "C" __global__ void moe_top1(
    float* out, const float* x, const float* expert0, const float* expert1, int width) {
  const unsigned linear = threadIdx.x + blockDim.x * (threadIdx.y + blockDim.y * threadIdx.z);
  if (linear != 0u) return;
  FI_OPEN(0);
  const int token = blockIdx.x;
  FI_B(EV_MOE, static_cast<unsigned>(token));
  const float score0 = expert_dot(x + token * width, expert0, width);
  const float score1 = expert_dot(x + token * width, expert1, width);
  const float gate = fmaxf(score0, score1);
  const float weight0 = expf(score0 - gate);
  const float weight1 = expf(score1 - gate);
  out[token] = (weight0 * score0 + weight1 * score1) / (weight0 + weight1);
  FI_E(EV_MOE, static_cast<unsigned>(token));
  FI_CLOSE();
}

#include <hip/hip_runtime.h>
#include "fi_lite_hip.h"
constexpr unsigned EV_CONVOLUTION = 14;

extern "C" __global__ void conv3x3_one_pixel(
    float* out, const float* in, const float* weight, int height, int width) {
  FI_OPEN(0);
  const int x = blockIdx.x * blockDim.x + threadIdx.x;
  const int y = blockIdx.y * blockDim.y + threadIdx.y;
  if (x < width && y < height) {
    const unsigned aux = static_cast<unsigned>(y * width + x);
    FI_B(EV_CONVOLUTION, aux);
    float acc = 0.0f;
    for (int ky = 0; ky < 3; ++ky) {
      for (int kx = 0; kx < 3; ++kx) {
        const int iy = min(max(y + ky - 1, 0), height - 1);
        const int ix = min(max(x + kx - 1, 0), width - 1);
        acc = fmaf(in[iy * width + ix], weight[ky * 3 + kx], acc);
      }
    }
    FI_E(EV_CONVOLUTION, aux);
    out[y * width + x] = acc;
  }
  FI_CLOSE();
}

#include <hip/hip_runtime.h>
#include "fi_lite_hip.h"
constexpr unsigned EV_MEGAKERNEL = 15;

extern "C" __global__ void persistent_copy(
    float* out, const float* in, unsigned* ticket, unsigned num_tiles) {
  __shared__ unsigned tile;
  FI_OPEN(0);
  for (;;) {
    if (threadIdx.x == 0) tile = atomicAdd(ticket, 1u);
    __syncthreads();
    if (tile >= num_tiles) break;
    FI_B(EV_MEGAKERNEL, tile);
    for (unsigned i = threadIdx.x; i < 1024u; i += blockDim.x) {
      out[tile * 1024u + i] = in[tile * 1024u + i];
    }
    FI_E(EV_MEGAKERNEL, tile);
    __syncthreads();
  }
  FI_CLOSE();
}

