extern "C" __global__ void affine_exp(float* out, const float* src, int count) {
  FI_OPEN(0);
  const int index = blockIdx.x * blockDim.x + threadIdx.x;
  if (index < count) {
    FI_B(EV_COMPUTE, static_cast<unsigned>(index));
    const float value = fmaf(exp2f(src[index]), 0.5f, 0.25f);
    FI_E(EV_COMPUTE, static_cast<unsigned>(index));
    out[index] = value;
