#include <hip/hip_runtime.h>
#include "fi_lite_hip.h"
constexpr unsigned EV_BARRIER = 7;

extern "C" __global__ void cta_handoff(float* dst, const float* src) {
  __shared__ float tile[256];
  FI_OPEN(0);
  const unsigned linear = threadIdx.x + blockDim.x * (threadIdx.y + blockDim.y * threadIdx.z);
  tile[linear] = src[blockIdx.x * blockDim.x + linear];
  if (linear == 0u) FI_B(EV_BARRIER, blockIdx.x);
  __syncthreads();
  if (linear == 0u) FI_E(EV_BARRIER, blockIdx.x);
  dst[blockIdx.x * blockDim.x + linear] = tile[255u - linear];
  FI_CLOSE();
}

#include <hip/hip_runtime.h>
#include "fi_lite_hip.h"
constexpr unsigned EV_DISPATCH = 8;

extern "C" __global__ void acquire_work(unsigned* ticket, unsigned* assigned) {
  const unsigned linear = threadIdx.x + blockDim.x * (threadIdx.y + blockDim.y * threadIdx.z);
  if (linear != 0u) return;
  FI_OPEN(0);
  FI_B(EV_DISPATCH, blockIdx.x);
  const unsigned work = atomicAdd(ticket, 1u);
  FI_E(EV_DISPATCH, blockIdx.x);
  assigned[blockIdx.x] = work;
  FI_CLOSE();
}

#include <hip/hip_runtime.h>
#include "fi_lite_hip.h"
constexpr unsigned EV_COMMUNICATION = 9;

extern "C" __global__ void rank_allreduce(
    float* value, volatile unsigned* peer_ready, volatile float* peer_value,
    unsigned rank, unsigned num_ranks, unsigned epoch) {
  const unsigned linear = threadIdx.x + blockDim.x * (threadIdx.y + blockDim.y * threadIdx.z);
  if (linear != 0u) return;
  FI_OPEN(0);
  FI_B(EV_COMMUNICATION, rank);
  peer_value[rank] = value[rank];
  __threadfence_system();
  peer_ready[rank] = epoch;
  for (unsigned peer = 0; peer < num_ranks; ++peer) {
    while (peer_ready[peer] != epoch) __nanosleep(64);
  }
  float total = 0.0f;
  for (unsigned peer = 0; peer < num_ranks; ++peer) total += peer_value[peer];
  value[rank] = total;
  FI_E(EV_COMMUNICATION, rank);
  FI_CLOSE();
}
